<?php $filter_action=base_url('weighted_exam/reports');$this->load->view('weighted_exam/_filters',get_defined_vars());?>
<?php if($rows):?><section class="panel"><header class="panel-heading"><h4 class="panel-title">Final Result and Completion Report</h4><div class="panel-btn"><a class="btn btn-default btn-circle" href="<?=current_url().'?'.http_build_query(['exam_id'=>$examId,'class_id'=>$classId,'section_id'=>$sectionId,'export'=>'csv'])?>"><i class="fas fa-file-csv"></i> CSV</a></div></header><div class="panel-body table-responsive"><table class="table table-bordered table-hover" id="weighted-report"><thead><tr><th>Roll</th><th>Register No.</th><th>Student</th><th>Percentage</th><th>Result</th><th>Position</th><th>Completion</th><th>Missing</th><th>Absent</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=$r['student']['roll']?></td><td><?=html_escape($r['student']['register_no'])?></td><td><?=html_escape($r['student']['student_name'])?></td><td><?=$r['result']?number_format($r['result']['overall_percentage'],2).'%':'—'?></td><td><?=html_escape($r['result']?$r['result']['result_label']:'Not Processed')?></td><td><?=$r['result']?$r['result']['class_position']:''?></td><td><span class="label label-<?=$r['calculation']['overall']['complete']?'success':'warning'?>"><?=$r['calculation']['overall']['complete']?'Complete':'Incomplete'?></span></td><td><?=$r['missing']?></td><td><?=$r['absent']?></td></tr><?php endforeach?></tbody></table></div></section><?php endif?>

